update public.products set description='Small edible land snails sold whole by piece count, with firm meat commonly prepared in peppered dishes, soups, stews and other thoroughly cooked meals.', handling_protocols=array['Do not eat snail raw or undercooked.','Wash hands thoroughly after handling raw or live snails and keep preparation water away from ready-to-eat foods.','Clean knives, boards, sinks and utensils thoroughly after preparation.','After shelling, clean as required with potable water and cook thoroughly throughout.']::text[], storage_tips=array['If supplied live, keep in a secure breathable container in a cool shaded place and process as soon as practical; do not seal live snails in an airtight bag.','If supplied as cleaned raw meat, refrigerate at 4°C or below and use within about 1–2 days or freeze promptly.','For cleaned frozen snail meat, a conservative best-quality target is about 2–3 months at -18°C or below.']::text[] where name='Snails - Small' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Large edible land snails sold whole by piece count, with substantial firm meat suitable for peppered snail, grilling, stews, soups and other thoroughly cooked dishes.', handling_protocols=array['Do not eat snail raw or undercooked.','Wash hands thoroughly after handling raw or live snails and keep preparation water away from ready-to-eat foods.','Clean knives, boards, sinks and utensils thoroughly after preparation.','After shelling, clean as required with potable water and cook thoroughly throughout.']::text[], storage_tips=array['If supplied live, keep in a secure breathable container in a cool shaded place and process as soon as practical; do not seal live snails in an airtight bag.','If supplied as cleaned raw meat, refrigerate at 4°C or below and use within about 1–2 days or freeze promptly.','For cleaned frozen snail meat, a conservative best-quality target is about 2–3 months at -18°C or below.']::text[] where name='Snails - Big' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
